To switch the order of adjectives in a sentence using JavaScript, you can split the sentence into an array of words, reverse the array containing the adjectives (starting from the second word), and then join the reversed adjective array with the first word (the subject) and the remaining words (everything after the last adjective). Here's the code:

```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(" "); // Split the sentence into an array of words
  let adjectives = []; // Create an empty array to store the adjectives

  // Loop through the words array and push each adjective (starting from the second word) into the adjectives array
  for (let I = 1; I < words.length; i++) {
    if (isAdjective(words[i])) { // Check if the current word is an adjective
      adjectives.unshift(words[i]); // Add the adjective to the beginning of the adjectives array
    }
  }

  // Join the reversed adjective array with the first word and the remaining words (after the last adjective)
  return [words[0], ...adjectives, ...words.slice(words.indexOf(adjectives[adjectives.length - 1]) + 1)].join(" ");
}

// Helper function to check if a word is an adjective or not
function isAdjective(word) {
  return /^[a-z]+[a-z'-\s]*[a-z]$/.test(word); // Regular expression to match common adjective patterns
}
```

