function myFunction() {
  // Define the range of cells containing place names
  const dataRange = sheet.getRange(2, 1, sheet.getLastRow() - 1, 1);

  // Loop through each cell in the range and perform geocoding
  const values = dataRange.getValues();
  for (let I = 0; I < values.length; i++) {
    const address = values[i][0];
    const response = Geocoding.geocode({
      address: address,
      location_type: 'ROOFTOP'
    });

    // Store latitude and longitude in corresponding columns
