```php
function smart_sort_array($set, $order) {
    usort($set, function($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];
        if ($ageA === $ageB) { // If ages are equal...
            return strnatcasecmp($a['name'], $b['name']); // Sort by name in natural order
        } else { // Otherwise, sort by age in reversed or normal order based on $order
            return ($order === 'DESC') ? $ageB - $ageA : $ageA - $ageB;
        }
    });
    return $set;
}
```

